import sys


def main():
    data = sys.stdin.buffer.read().split(b'\n')
    sums = {}
    get = sums.get
    for line in data[1:]:
        p = line.split(b',')
        if len(p) < 3:
            continue
        cat = p[1]
        sums[cat] = get(cat, 0.0) + float(p[2])
    out = [b'%s,%.2f' % (c, sums[c]) for c in sorted(sums)]
    if out:
        sys.stdout.buffer.write(b'\n'.join(out) + b'\n')


if __name__ == '__main__':
    main()
